        meaning: 'Miliknya (lk/pr) / Milik mereka / Milik kami (+ Benda)',
        mnemonic: 'Hati-hati membedakan bunyi kembar: \'their\' (milik mereka), \'there\' (di sana), dan \'they\'re\' (mereka adalah)!',
