      explanation: 'Modal \'can\' tidak pernah berubah bentuk untuk subjek apa pun (She can speak—BUKAN \'She cans\' dan BUKAN \'She can speaks\' atau \'She can to speak\'). Selalu ikuti \'can/can\'t\' langsung dengan kata kerja dasar V1.',
