      formulaReading: 'What\'s the weather like? /wʌts ðə ˈweðər laɪk/ = Bagaimana cuacanya?',
      explanation: 'Jangan mencampur kata sifat cuaca (\'rainy\', \'snowy\') dengan kata kerja cuaca (\'rain\', \'snow\')! Katakan \'It is rainy\' ATAU \'It is raining\' (jangan \'It is rain\'!). Untuk menanyakan cuaca, gunakan \'What\'s the weather like today?\'.',
