    contrastiveTip: 'Jebakan L1 Bahasa Indonesia: \'mengikuti ujian/kelas\' JANGAN diterjemahkan \'follow the exam/class\' (itu artinya membuntuti dari belakang!). Gunakan \'take an exam\' dan \'take a class\'!',
