        reading: '/aɪm ˈɡoʊɪŋ tə/',
        meaning: 'Saya sudah berencana akan... (diputuskan SEBELUM bicara)',
        mnemonic: 'Sudah ada niat/persiapan sebelumnya: \'I\'m going to visit my cousin in Dallas next week.\'',
        speakText: 'We\'re going to launch on Monday.',
