        reading: '/plæn tə / hoʊp tə/',
        meaning: 'Berencana untuk / Berharap untuk...',
        mnemonic: 'Cara halus dan profesional menceritakan aspirasi karier dalam wawancara beasiswa.',
        speakText: 'I hope to specialize in renewable energy.',
