    grammarSummary: {
      code: 'GP-EN-A2-002',
      title: 'Infinitive of Purpose (to + V1) vs Preposition (for + Noun)',
      formula: 'Action + to + Base Verb (V1) [Tujuan Aksi] • Action + for + Noun [Manfaat Benda]',
      formulaReading: 'BENAR: I moved here to study • SALAH: I moved here for study',
      explanation: 'Aturan emas penerjemahan kata \'untuk\': lihat kata tepat di belakangnya! Kalau kata kerja (belajar, melamar, menabung), pakai \'TO + V1\' (\'to study\', \'to apply\', \'to save\'). Kalau kata benda (konferensi, wawancara, masa depan), pakai \'FOR + Noun\' (\'for a conference\', \'for my interview\').',
      examples: [
        { jp: 'She\'s saving money to take a summer course in Boston.', reading: '/ʃiːz ˈseɪvɪŋ ˈmʌni tə teɪk ə ˈsʌmər kɔːrs ɪn ˈbɑːstən/', id: 'Dia sedang menabung uang untuk mengambil kursus musim panas di Boston.' },
        { jp: 'In the long run, I hope to build healthcare technology for rural clinics.', reading: '/ɪn ðə lɔːŋ rʌn, aɪ hoʊp tə bɪld ˈhelθker tekˈnɑːlədʒi fɔːr ˈrʊrəl ˈklɪnɪks/', id: 'Dalam jangka panjang, saya berharap membangun teknologi kesehatan untuk klinik-klinik daerah.' },
      ],
    },
    contrastiveTip: 'Di AS, daftar riwayat hidup (CV singkat 1 halaman untuk melamar kerja industri) disebut \'resume\' (/ˈrezəmeɪ/)—sedangkan istilah \'CV\' di AS hanya dipakai untuk akademisi/dosen/peneliti!',
