  'en-a2-u3-pola-kalimat': {
    headline: 'Menilai Kondisi Tempat Tinggal: Too Much, Too Many & Enough',
    subtitle: 'Saat membandingkan kamar asrama atau apartemen, kita sering menilai cahaya matahari, kebisingan jalan, ruang lemari, atau jumlah stopkontak!',
    items: [
      {
        symbol: 'too much + Uncountable Noun',
        reading: '/tuː mʌtʃ/',
        meaning: 'Terlalu banyak... (benda tak terhitung: noise, traffic, space)',
        mnemonic: 'Contoh: \'There\'s too much street noise at night.\'',
        speakText: 'There\'s too much traffic on this street.',
      },
      {
        symbol: 'too many + Plural Noun',
        reading: '/tuː ˈmeni/',
        meaning: 'Terlalu banyak... (benda jamak terhitung: stairs, people, rules)',
        mnemonic: 'Contoh: \'Four roommates are too many people for one bathroom!\'',
        speakText: 'There are too many stairs with no elevator.',
      },
      {
        symbol: 'enough + Noun / Adjective + enough',
        reading: '/ɪˈnʌf/',
        meaning: 'Cukup... (PERHATIKAN POSISI \'enough\'!)',
        mnemonic: 'SEBELUM kata benda (\'enough closet space\'), tetapi SETELAH kata sifat (\'quiet enough\' — BUKAN \'enough quiet\')!',
        speakText: 'Is the bedroom big enough?',
      },
      {
        symbol: 'plenty of / a lot of',
        reading: '/ˈplenti ʌv / ə lɑːt ʌv/',
        meaning: 'Banyak sekali / lebih dari cukup (bisa untuk tunggal tak terhitung maupun jamak!)',
        mnemonic: 'Sangat fleksibel untuk hal positif: \'plenty of natural light\' & \'plenty of outlets\'.',
        speakText: 'The living room gets plenty of sunlight.',
      },
    ],
    grammarSummary: {
      code: 'GP-EN-A2-003',
      title: 'Quantifiers & Posisi Kata \'Enough\'',
      formula: 'too much + Uncountable • too many + Plural • enough + Noun • Adjective + enough',
      formulaReading: 'enough space (enough + Benda) vs spacious enough (Sifat + enough)!',
      explanation: 'Jebakan posisi \'enough\' sering muncul di tes bahasa Inggris: dalam Bahasa Indonesia kita selalu berkata \'cukup besar\' (\'cukup\' di depan). Dalam Bahasa Inggris, untuk kata sifat urutannya TERBALIK menjadi \'big enough\' (\'quiet enough\', \'close enough\'), sedangkan untuk kata benda tetap \'enough space\' (\'enough chairs\')!',
      examples: [
        { jp: 'This studio is bright, but there isn\'t enough closet space.', reading: '/ðɪs ˈstuːdioʊ ɪz braɪt, bʌt ðer ˈɪzənt ɪˈnʌf ˈklɑːzɪt speɪs/', id: 'Apartemen studio ini terang, tetapi ruang lemarinya kurang cukup.' },
        { jp: 'The neighborhood is quiet enough to study at night.', reading: '/ðə ˈneɪbərhʊd ɪz ˈkwaɪət ɪˈnʌf tə ˈstʌdi æt naɪt/', id: 'Lingkungan sekitarnya cukup tenang untuk belajar pada malam hari.' },
      ],
    },
    contrastiveTip: 'Ingat lafal \'enough\' adalah /ɪˈnʌf/ (akhiran \'gh\' berbunyi /f/!), dan jangan pernah menulis \'enough big\'—selalu \'big enough\'!',
  },
