    contrastiveTip: 'Bedakan \'headache\' (kepala nyeri/cenut-cenut) dengan \'dizzy\' (kepala kliyengan/berputar seperti mau pingsan: \'I feel dizzy\', BUKAN \'I have a dizzy\')!',
