    contrastiveTip: 'Jangan pernah tertukar format tanggal AS (MM/DD/YYYY) di formulir klinik atau visa! Supaya 100% bebas salah paham saat berbicara, sebutkan nama bulannya: \'July fourth, two thousand two\'.',
