      explanation: 'Catatan perbedaan US vs UK: buku lama sering mengajarkan \'Shall I carry your bag?\'. Di Amerika Serikat modern, kata \'Shall I...?\' hampir TIDAK PERNAH dipakai dalam percakapan sehari-hari (terdengar seperti drama kerajaan abad ke-19!). Orang Amerika selalu memakai \'Would you like me to...?\', \'Do you want me to...?\', atau \'Should I...?\'!',
