    contrastiveTip: 'Jangan terkecoh kata \'for\'! Banyak pelajar menghafal rumus kaku \'Kalau ada kata FOR pasti Present Perfect\'—ITU KELIRU! \'For\' bisa dipakai di semua tense (\'I waited for ten minutes yesterday\' = Past Simple; \'I\'ll stay in Austin for three days\' = Future)!',
