    grammarSummary: {
      code: 'GP-EN-B1-002',
      title: 'Present Perfect Continuous: Ongoing Action Duration (Have / Has Been + V-ing)',
      formula: 'I/You/We/They + have (\'ve) been + V-ing • He/She/It + has (\'s) been + V-ing',
      formulaReading: 'I\'ve been (/aɪv bɪn/) working • She\'s been (/ʃiːz bɪn/) waiting',
      explanation: 'Bayangkan kamu tiba di halte bus pukul 08.00, dan sekarang pukul 08.30 kamu MASIH berdiri menunggu bus itu. Jika kamu berkata \'I am waiting\', orang tidak tahu sudah 30 menit. Jika kamu berkata \'I\'ve been waiting for thirty minutes!\', durasi 30 menit DAN fakta bahwa kamu masih menunggu tersampaikan sekaligus!',
      examples: [
        { jp: 'Our team has been preparing for the product launch since early March.', reading: '/ˈaʊər tiːm hæz bɪn prɪˈperɪŋ fɔːr ðə ˈprɑːdʌkt lɔːntʃ sɪns ˈɜːrli mɑːrtʃ/', id: 'Tim kami terus mempersiapkan peluncuran produk sejak awal Maret.' },
        { jp: 'How long have you been learning American English?', reading: '/haʊ lɔːŋ hæv juː bɪn ˈlɜːrnɪŋ əˈmerɪkən ˈɪŋɡlɪʃ/', id: 'Sudah berapa lama kamu belajar Bahasa Inggris Amerika?' },
      ],
    },
    contrastiveTip: 'Dalam percakapan cepat Amerika, \'I have been\' menyatu lembut menjadi /aɪv bɪn/ (BUKAN /aɪ hæv biːn/). Hindari menerjemahkan \'Saya sudah menunggu dua jam\' dengan Present Continuous (\'I am waiting for two hours\' — SALAH BESAR!)!',
